llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C40"],
      "claim": "Perindoprilat, the diacid active metabolite of perindopril, has a mean oral bioavailability of 19% ± 7% in young healthy subjects after oral prodrug administration; as a highly ionized carboxylic acid with multiple polar groups, it is the closest acid analogue and supports low F (<20%) for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Warfarin, a lipophilic carboxylic acid, has nearly complete oral bioavailability; this is contradictory to low but less applicable because warfarin is smaller, more lipophilic, and lacks the multiple hydroxyl/ether polar groups of the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C34"],
      "claim": "TP-434 (eravacycline) has 28% oral bioavailability; contradictory to low but it is a zwitterionic tetracycline with a basic amine, not a simple ionized carboxylic acid, so its absorption mechanism differs from the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C11"],
      "claim": "Perindopril ester prodrug has about 75% oral bioavailability; contradictory to low but it is an ester prodrug that masks the carboxylic acid, whereas the query is the free acid and would not benefit from this prodrug effect.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a fully ionized carboxylic acid with low logD, high TPSA, and multiple polar hydroxyl/ether groups, predicting poor passive permeability. The most mechanistically relevant acid analogue, perindoprilat, has F ≈ 19%, below the 20% threshold. High-F analogues are mostly basic amines, ester prodrugs, or lipophilic/zwitterionic molecules whose absorption advantages do not apply to the query's free-acid, polar scaffold. Therefore low oral bioavailability is better supported.",
  "evidence_gaps": [
    "No direct oral bioavailability data exist for the exact query or a close non-prodrug acid analogue.",
    "Perindoprilat data are derived from oral prodrug administration, not direct oral dosing of the free acid.",
    "Potential active transport, efflux, or prodrug strategies for the query are unknown.",
    "Physicochemical estimates (logD, pKa) are uncertain and may not fully capture permeability behavior."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

